// Package gyaml implements the subset of YAML needed by gomplate: parsing
// documents into a generic node tree, resolving untagged scalars per the
// YAML 1.2 core schema (plus the timestamp and legacy-octal extensions that
// the reference implementation supports), and emitting values back out.
package gyaml

import "fmt"

// Kind describes what a Node holds.
type Kind int

const (
	ScalarNode Kind = iota
	MappingNode
	SequenceNode
	AliasNode
)

// Style records how a scalar was written, which matters because quoting
// suppresses tag resolution.
type Style int

const (
	Plain Style = iota
	SingleQuoted
	DoubleQuoted
	Literal
	Folded
)

// Node is one YAML node. Mapping children alternate key, value, key, value...
type Node struct {
	Kind     Kind
	Style    Style
	Tag      string
	Value    string
	Anchor   string
	Children []*Node
	Line     int
}

// TypeError collects the "cannot unmarshal" style complaints that the
// reference implementation reports all at once.
type TypeError struct {
	Errors []string
}

func (e *TypeError) Error() string {
	s := "yaml: unmarshal errors:"
	for _, err := range e.Errors {
		s += "\n  " + err
	}
	return s
}

func typeErrorf(format string, args ...any) error {
	return &TypeError{Errors: []string{fmt.Sprintf(format, args...)}}
}

