package gyaml

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

type parser struct {
	lines []string
}

// Parse splits the input into documents and returns the root node of each.
func Parse(data []byte) ([]*Node, error) {
	text := string(data)
	text = strings.ReplaceAll(text, "\r\n", "\n")
	text = strings.ReplaceAll(text, "\r", "\n")
	text = strings.TrimSuffix(text, "\n")
	p := &parser{}
	if text != "" || len(data) > 0 {
		p.lines = strings.Split(text, "\n")
	}
	pos := 0
	var docs []*Node
	for {
		n, next, ok, err := p.parseDocument(pos)
		if err != nil {
			return nil, err
		}
		if !ok {
			break
		}
		docs = append(docs, n)
		pos = next
	}
	return docs, nil
}

func indentOf(s string) int {
	i := 0
	for i < len(s) && s[i] == ' ' {
		i++
	}
	return i
}

func isBlankLine(s string) bool {
	t := strings.TrimLeft(s, " \t")
	return t == "" || t[0] == '#'
}

func isDocStart(s string) bool {
	return s == "---" || strings.HasPrefix(s, "--- ") || strings.HasPrefix(s, "---\t")
}

func isDocEnd(s string) bool {
	return s == "..." || strings.HasPrefix(s, "... ")
}

// at returns the indent and de-indented content of a meaningful line, skipping
// blanks and comments. ok is false at EOF or at a document boundary.
func (p *parser) at(pos int) (newPos, indent int, content string, ok bool) {
	for pos < len(p.lines) {
		l := p.lines[pos]
		if isBlankLine(l) {
			pos++
			continue
		}
		ind := indentOf(l)
		c := l[ind:]
		if ind == 0 && (isDocStart(c) || isDocEnd(c)) {
			return pos, 0, "", false
		}
		return pos, ind, c, true
	}
	return pos, 0, "", false
}

func (p *parser) parseDocument(pos int) (*Node, int, bool, error) {
	// skip leading blanks, directives and end-markers
	sawStart := false
	for pos < len(p.lines) {
		l := p.lines[pos]
		if isBlankLine(l) {
			pos++
			continue
		}
		ind := indentOf(l)
		c := l[ind:]
		if ind == 0 && strings.HasPrefix(c, "%") {
			pos++
			continue
		}
		if ind == 0 && isDocEnd(c) {
			pos++
			continue
		}
		if ind == 0 && isDocStart(c) {
			sawStart = true
			rest := strings.TrimSpace(strings.TrimPrefix(c, "---"))
			if rest == "" || strings.HasPrefix(rest, "#") {
				pos++
				continue
			}
			// content on the same line as the marker
			p.lines[pos] = strings.Repeat(" ", 4) + rest
			break
		}
		break
	}
	if pos >= len(p.lines) {
		if sawStart {
			return &Node{Kind: ScalarNode, Tag: "!!null", Line: pos + 1}, pos, true, nil
		}
		return nil, pos, false, nil
	}
	n, next, err := p.parseBlock(pos, 0, 0)
	if err != nil {
		return nil, 0, false, err
	}
	return n, next, true, nil
}

// parseBlock parses the node beginning at line pos. indent is the column the
// node starts at; minFold is the minimum indentation for plain-scalar
// continuation lines.
func (p *parser) parseBlock(pos, indent, minFold int) (*Node, int, error) {
	pos, ind, content, ok := p.at(pos)
	if !ok || ind < indent {
		return &Node{Kind: ScalarNode, Tag: "!!null", Line: pos + 1}, pos, nil
	}
	if isSeqEntry(content) {
		return p.parseSeq(pos, ind)
	}
	if k := findKeyColon(content); k >= 0 {
		return p.parseMap(pos, ind)
	}
	return p.parseInline(pos, ind, content, minFold)
}

func isSeqEntry(c string) bool {
	if c == "-" {
		return true
	}
	return len(c) > 1 && c[0] == '-' && (c[1] == ' ' || c[1] == '\t')
}

// findKeyColon reports the offset of the ':' that ends an implicit mapping key,
// or -1 when the line does not start a mapping entry.
func findKeyColon(c string) int {
	i := 0
	// explicit key indicator
	if c == "?" || strings.HasPrefix(c, "? ") {
		return -1
	}
	if i < len(c) && (c[i] == '&' || c[i] == '!') {
		// node properties before the key are not supported for keys
		return -1
	}
	if i < len(c) && (c[i] == '\'' || c[i] == '"') {
		q := c[i]
		i++
		for i < len(c) {
			if c[i] == '\\' && q == '"' {
				i += 2
				continue
			}
			if c[i] == q {
				if q == '\'' && i+1 < len(c) && c[i+1] == '\'' {
					i += 2
					continue
				}
				i++
				break
			}
			i++
		}
		for i < len(c) && c[i] == ' ' {
			i++
		}
		if i < len(c) && c[i] == ':' && (i+1 == len(c) || c[i+1] == ' ' || c[i+1] == '\t') {
			return i
		}
		return -1
	}
	depth := 0
	for i < len(c) {
		switch c[i] {
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case '\'', '"':
			q := c[i]
			i++
			for i < len(c) {
				if c[i] == '\\' && q == '"' {
					i += 2
					continue
				}
				if c[i] == q {
					break
				}
				i++
			}
		case '#':
			if i > 0 && (c[i-1] == ' ' || c[i-1] == '\t') {
				return -1
			}
		case ':':
			if depth == 0 && (i+1 == len(c) || c[i+1] == ' ' || c[i+1] == '\t') {
				return i
			}
		}
		i++
	}
	return -1
}

func (p *parser) parseSeq(pos, ind int) (*Node, int, error) {
	node := &Node{Kind: SequenceNode, Line: pos + 1}
	for {
		np, i, content, ok := p.at(pos)
		if !ok || i != ind || !isSeqEntry(content) {
			pos = np
			break
		}
		pos = np
		rest := content[1:]
		lead := 0
		for lead < len(rest) && (rest[lead] == ' ' || rest[lead] == '\t') {
			lead++
		}
		body := rest[lead:]
		if body == "" || strings.HasPrefix(body, "#") {
			pos++
			// value on following lines
			np2, i2, _, ok2 := p.at(pos)
			if ok2 && i2 > ind {
				child, next, err := p.parseBlock(np2, i2, i2)
				if err != nil {
					return nil, 0, err
				}
				node.Children = append(node.Children, child)
				pos = next
				continue
			}
			node.Children = append(node.Children, &Node{Kind: ScalarNode, Tag: "!!null", Line: pos})
			pos = np2
			continue
		}
		col := ind + 1 + lead
		p.lines[pos] = strings.Repeat(" ", col) + body
		child, next, err := p.parseBlock(pos, col, col)
		if err != nil {
			return nil, 0, err
		}
		node.Children = append(node.Children, child)
		pos = next
	}
	return node, pos, nil
}

func (p *parser) parseMap(pos, ind int) (*Node, int, error) {
	node := &Node{Kind: MappingNode, Line: pos + 1}
	for {
		np, i, content, ok := p.at(pos)
		if !ok || i != ind {
			pos = np
			break
		}
		pos = np
		if isSeqEntry(content) {
			break
		}
		k := findKeyColon(content)
		if k < 0 {
			return nil, 0, fmt.Errorf("yaml: line %d: could not find expected ':'", pos+1)
		}
		keyText := strings.TrimRight(content[:k], " \t")
		keyNode, err := p.scalarFromText(keyText, pos+1)
		if err != nil {
			return nil, 0, err
		}
		valRaw := content[k+1:]
		lead := 0
		for lead < len(valRaw) && (valRaw[lead] == ' ' || valRaw[lead] == '\t') {
			lead++
		}
		body := valRaw[lead:]
		if body == "" || strings.HasPrefix(body, "#") {
			pos++
			np2, i2, c2, ok2 := p.at(pos)
			var val *Node
			var next int
			switch {
			case ok2 && i2 > ind:
				val, next, err = p.parseBlock(np2, i2, i2)
			case ok2 && i2 == ind && isSeqEntry(c2):
				val, next, err = p.parseSeq(np2, i2)
			default:
				val, next = &Node{Kind: ScalarNode, Tag: "!!null", Line: pos}, np2
			}
			if err != nil {
				return nil, 0, err
			}
			node.Children = append(node.Children, keyNode, val)
			pos = next
			continue
		}
		col := ind + k + 1 + lead
		p.lines[pos] = strings.Repeat(" ", col) + body
		val, next, err := p.parseInline(pos, col, body, ind+1)
		if err != nil {
			return nil, 0, err
		}
		node.Children = append(node.Children, keyNode, val)
		pos = next
	}
	return node, pos, nil
}

// parseInline handles a node whose content starts on line pos at column indent.
func (p *parser) parseInline(pos, indent, content string2, minFold int) (*Node, int, error) {
