package gyaml

import (
	"fmt"
	"strconv"
	"strings"
	"unicode/utf8"
)

// parseInline handles a node whose content begins on line pos at column indent.
// minFold is the minimum indentation of a plain scalar continuation line.
func (p *parser) parseInline(pos, indent int, content string, minFold int) (*Node, int, error) {
	anchor, tag, rest, err := splitProperties(content)
	if err != nil {
		return nil, 0, err
	}
	if rest == "" || strings.HasPrefix(rest, "#") {
		// properties alone on the line; value is on following lines
		p.lines[pos] = strings.Repeat(" ", indent) + rest
		pos++
		np, i2, c2, ok := p.at(pos)
		var n *Node
		var next int
		switch {
		case ok && i2 > indent:
			n, next, err = p.parseBlock(np, i2, i2)
		case ok && i2 == indent && isSeqEntry(c2):
			n, next, err = p.parseSeq(np, i2)
		default:
			n, next = &Node{Kind: ScalarNode, Tag: "!!null", Line: pos}, np
		}
		if err != nil {
			return nil, 0, err
		}
		n.Anchor = anchor
		if tag != "" {
			n.Tag = tag
		}
		p.register(n)
		return n, next, nil
	}
	if strings.HasPrefix(rest, "*") {
		name := strings.TrimSpace(strings.TrimSuffix(strings.Fields(rest)[0], ","))[1:]
		return &Node{Kind: AliasNode, Value: name, Line: pos + 1}, pos + 1, nil
	}
	off := indent + (len(content) - len(rest))
	var n *Node
	var next int
	switch rest[0] {
	case '|', '>':
		n, next, err = p.parseBlockScalar(pos, indent, rest)
	case '[', '{':
		n, next, err = p.parseFlow(pos, off)
	case '\'', '"':
		n, next, err = p.parseQuoted(pos, off, minFold)
	default:
		n, next, err = p.parsePlain(pos, off, minFold)
	}
	if err != nil {
		return nil, 0, err
	}
	n.Anchor = anchor
	if tag != "" {
		n.Tag = tag
	}
	p.register(n)
	return n, next, nil
}

func (p *parser) register(n *Node) {
	if n.Anchor == "" {
		return
	}
	if p.anchors == nil {
		p.anchors = map[string]*Node{}
	}
	p.anchors[n.Anchor] = n
}

// splitProperties strips leading anchor and tag indicators.
func splitProperties(s string) (anchor, tag, rest string, err error) {
	rest = s
	for i := 0; i < 2; i++ {
		switch {
		case strings.HasPrefix(rest, "&"):
			f := rest[1:]
			end := strings.IndexAny(f, " \t")
			if end < 0 {
				anchor, rest = f, ""
			} else {
				anchor, rest = f[:end], strings.TrimLeft(f[end:], " \t")
			}
		case strings.HasPrefix(rest, "!"):
			end := strings.IndexAny(rest, " \t")
			if end < 0 {
				tag, rest = rest, ""
			} else {
				tag, rest = rest[:end], strings.TrimLeft(rest[end:], " \t")
			}
			tag = normalizeTag(tag)
		default:
			return anchor, tag, rest, nil
		}
	}
	return anchor, tag, rest, nil
}

func normalizeTag(t string) string {
	switch t {
	case "!!str", "!!int", "!!float", "!!bool", "!!null", "!!map", "!!seq", "!!binary", "!!timestamp":
		return t
	case "!":
		return "!!str"
	}
	if strings.HasPrefix(t, "!!") {
		return t
	}
	return t
}

// parseBlockScalar handles literal (|) and folded (>) scalars.
func (p *parser) parseBlockScalar(pos, indent int, header string) (*Node, int, error) {
	style := Literal
	if header[0] == '>' {
		style = Folded
	}
	h := header[1:]
	if i := strings.IndexByte(h, '#'); i >= 0 {
		h = h[:i]
	}
	h = strings.TrimSpace(h)
	chomp := byte(0)
	explicit := 0
	for i := 0; i < len(h); i++ {
		switch {
		case h[i] == '-' || h[i] == '+':
			chomp = h[i]
		case h[i] >= '1' && h[i] <= '9':
			explicit = int(h[i] - '0')
		}
	}
	pos++
