	trailing := 0
	for len(raw) > 0 && raw[len(raw)-1] == "" {
		raw = raw[:len(raw)-1]
		trailing++
	}
	var sb strings.Builder
	if style == Literal {
		for _, l := range raw {
			sb.WriteString(l)
			sb.WriteByte('\n')
		}
	} else {
		for i, l := range raw {
			if i > 0 {
				prev := raw[i-1]
				switch {
				case prev == "":
					// blank lines already emitted a newline
				case strings.HasPrefix(l, " ") || strings.HasPrefix(prev, " "):
					sb.WriteByte('\n')
				case l == "":
				default:
					sb.WriteByte(' ')
				}
			}
			if l == "" {
				sb.WriteByte('\n')
				continue
			}
			sb.WriteString(l)
		}
		if len(raw) > 0 {
			sb.WriteByte('\n')
		}
	}
	val := sb.String()
	switch chomp {
	case '-':
		val = strings.TrimRight(val, "\n")
	case '+':
		val += strings.Repeat("\n", trailing)
	default:
		val = strings.TrimRight(val, "\n")
		if len(raw) > 0 {
			val += "\n"
		}
	}
	return &Node{Kind: ScalarNode, Style: style, Tag: "!!str", Value: val, Line: pos}, pos, nil
}

// cursor walks characters across lines, used for flow collections and
// multi-line quoted scalars.
type cursor struct {
	p    *parser
	line int
	col  int
}

func (c *cursor) eof() bool { return c.line >= len(c.p.lines) }

func (c *cursor) peek() byte {
	if c.eof() {
		return 0
	}
	l := c.p.lines[c.line]
	if c.col >= len(l) {
		return '\n'
	}
	return l[c.col]
}

func (c *cursor) next() byte {
	b := c.peek()
	if b == '\n' {
		c.line++
		c.col = 0
	} else {
		c.col++
	}
	return b
}

func (c *cursor) skipWS(allowComments bool) {
	for !c.eof() {
		b := c.peek()
		if b == ' ' || b == '\t' || b == '\n' {
			c.next()
			continue
		}
		if allowComments && b == '#' {
			c.line++
			c.col = 0
			continue
		}
		return
	}
}

func (p *parser) parseFlow(pos, col int) (*Node, int, error) {
	c := &cursor{p: p, line: pos, col: col}
	n, err := p.flowNode(c)
	if err != nil {
		return nil, 0, err
	}
	next := c.line
	// consume the rest of the line if only a comment remains
	if next < len(p.lines) {
		rest := strings.TrimSpace(p.lines[next][min(c.col, len(p.lines[next])):])
		if rest == "" || strings.HasPrefix(rest, "#") {
			next++
		}
	}
	return n, next, nil
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func (p *parser) flowNode(c *cursor) (*Node, error) {
	c.skipWS(true)
	line := c.line + 1
	switch c.peek() {
	case '[':
		c.next()
		n := &Node{Kind: SequenceNode, Line: line}
		for {
			c.skipWS(true)
			if c.eof() {
				return nil, fmt.Errorf("yaml: line %d: did not find expected ',' or ']'", line)
			}
			if c.peek() == ']' {
				c.next()
				return n, nil
			}
			item, err := p.flowNode(c)
			if err != nil {
				return nil, err
			}
			n.Children = append(n.Children, item)
			c.skipWS(true)
			if c.peek() == ',' {
				c.next()
				continue
			}
			if c.peek() == ']' {
				c.next()
				return n, nil
			}
			return nil, fmt.Errorf("yaml: line %d: did not find expected ',' or ']'", c.line+1)
		}
	case '{':
		c.next()
		n := &Node{Kind: MappingNode, Line: line}
		for {
			c.skipWS(true)
			if c.eof() {
				return nil, fmt.Errorf("yaml: line %d: did not find expected ',' or '}'", line)
			}
			if c.peek() == '}' {
				c.next()
				return n, nil
			}
			key, err := p.flowNode(c)
			if err != nil {
				return nil, err
			}
			c.skipWS(true)
			var val *Node
			if c.peek() == ':' {
				c.next()
				val, err = p.flowNode(c)
				if err != nil {
					return nil, err
				}
			} else {
				val = &Node{Kind: ScalarNode, Tag: "!!null", Line: c.line + 1}
			}
			n.Children = append(n.Children, key, val)
			c.skipWS(true)
			if c.peek() == ',' {
				c.next()
				continue
			}
			if c.peek() == '}' {
				c.next()
				return n, nil
			}
			return nil, fmt.Errorf("yaml: line %d: did not find expected ',' or '}'", c.line+1)
		}
	case '\'', '"':
		return p.readQuoted(c)
	case '*':
		c.next()
		var sb strings.Builder
		for !c.eof() {
			b := c.peek()
			if b == ',' || b == ']' || b == '}' || b == ' ' || b == '\n' || b == '\t' {
				break
			}
			sb.WriteByte(c.next())
		}
		return &Node{Kind: AliasNode, Value: sb.String(), Line: line}, nil
	}
	// plain scalar inside flow context
	var sb strings.Builder
	spaces := 0
	for !c.eof() {
		b := c.peek()
		if b == ',' || b == ']' || b == '}' {
			break
		}
		if b == ':' {
			// a colon terminates a plain key inside a flow mapping
			nl := c.col + 1
			var nb byte = '\n'
			if nl < len(c.p.lines[c.line]) {
				nb = c.p.lines[c.line][nl]
			}
			if nb == ' ' || nb == '\n' || nb == ',' || nb == '}' || nb == ']' {
				break
			}
		}
		if b == '\n' {
			c.next()
			spaces = 1
			continue
		}
		if b == ' ' || b == '\t' {
			c.next()
			spaces++
			continue
		}
		if b == '#' && spaces > 0 {
			c.line++
			c.col = 0
			spaces = 1
			continue
		}
		if spaces > 0 && sb.Len() > 0 {
			sb.WriteByte(' ')
		}
		spaces = 0
		sb.WriteByte(c.next())
	}
	return &Node{Kind: ScalarNode, Style: Plain, Value: sb.String(), Line: line}, nil
}

func (p *parser) parseQuoted(pos, col, minFold int) (*Node, int, error) {
	c := &cursor{p: p, line: pos, col: col}
	n, err := p.readQuoted(c)
	if err != nil {
		return nil, 0, err
	}
	next := c.line
	if next < len(p.lines) {
		l := p.lines[next]
		rest := ""
		if c.col < len(l) {
			rest = strings.TrimSpace(l[c.col:])
		}
		if rest == "" || strings.HasPrefix(rest, "#") {
			next++
		}
	}
	return n, next, nil
}

func (p *parser) readQuoted(c *cursor) (*Node, error) {
	line := c.line + 1
	q := c.next()
	var sb strings.Builder
	pendingNL := 0
	sawSpace := false
	flush := func() {
		switch {
		case pendingNL == 0:
			if sawSpace {
				sb.WriteByte(' ')
			}
		case pendingNL == 1:
			sb.WriteByte(' ')
		default:
			sb.WriteString(strings.Repeat("\n", pendingNL-1))
		}
		pendingNL = 0
		sawSpace = false
	}
	for {
		if c.eof() {
			return nil, fmt.Errorf("yaml: line %d: found unexpected end of stream", line)
		}
		b := c.peek()
		if b == '\n' {
			c.next()
			pendingNL++
			// trim leading whitespace of the next line
			for c.peek() == ' ' || c.peek() == '\t' {
				c.next()
			}
			continue
		}
		if pendingNL > 0 || sawSpace {
			// only emit folding once we know real content follows
			if b == q {
				// closing quote right after folding
				if pendingNL > 0 {
					flush()
				} else if sawSpace {
					sb.WriteByte(' ')
					sawSpace = false
				}
				c.next()
				style := SingleQuoted
				if q == '"' {
					style = DoubleQuoted
				}
				return &Node{Kind: ScalarNode, Style: style, Tag: "!!str", Value: sb.String(), Line: line}, nil
			}
			flush()
		}
		if b == ' ' || b == '\t' {
			c.next()
			sawSpace = true
			continue
		}
		if b == q {
			c.next()
			if q == '\'' && c.peek() == '\'' {
				c.next()
				sb.WriteByte('\'')
				continue
			}
			style := SingleQuoted
			if q == '"' {
				style = DoubleQuoted
			}
			return &Node{Kind: ScalarNode, Style: style, Tag: "!!str", Value: sb.String(), Line: line}, nil
		}
		if q == '"' && b == '\\' {
			c.next()
			e := c.peek()
			if e == '\n' {
				c.next()
				for c.peek() == ' ' || c.peek() == '\t' {
					c.next()
				}
				continue
			}
			c.next()
			switch e {
			case '0':
				sb.WriteByte(0)
			case 'a':
				sb.WriteByte(7)
			case 'b':
				sb.WriteByte(8)
			case 't', '\t':
				sb.WriteByte('\t')
			case 'n':
				sb.WriteByte('\n')
			case 'v':
				sb.WriteByte(11)
			case 'f':
				sb.WriteByte(12)
			case 'r':
				sb.WriteByte('\r')
			case 'e':
				sb.WriteByte(27)
			case ' ':
				sb.WriteByte(' ')
			case '"':
				sb.WriteByte('"')
			case '/':
				sb.WriteByte('/')
			case '\\':
				sb.WriteByte('\\')
			case 'N':
				sb.WriteString("")
			case '_':
				sb.WriteString(" ")
			case 'L':
				sb.WriteString(" ")
			case 'P':
				sb.WriteString(" ")
			case 'x', 'u', 'U':
				n := map[byte]int{'x': 2, 'u': 4, 'U': 8}[e]
				var hex strings.Builder
				for i := 0; i < n; i++ {
					hex.WriteByte(c.next())
				}
				v, err := strconv.ParseUint(hex.String(), 16, 32)
				if err != nil {
					return nil, fmt.Errorf("yaml: line %d: found unknown escape character", line)
				}
				var buf [4]byte
				sb.Write(buf[:utf8.EncodeRune(buf[:], rune(v))])
			default:
				return nil, fmt.Errorf("yaml: line %d: found unknown escape character %q", line, string(e))
			}
			continue
		}
		sb.WriteByte(c.next())
	}
}

func (p *parser) parsePlain(pos, col, minFold int) (*Node, int, error) {
	line := p.lines[pos]
	text := line[min(col, len(line)):]
	text = stripComment(text)
	var parts []string
	parts = append(parts, strings.TrimRight(text, " \t"))
	pos++
	blanks := 0
	for pos < len(p.lines) {
		l := p.lines[pos]
		if strings.TrimLeft(l, " \t") == "" {
			blanks++
			pos++
			continue
		}
		ind := indentOf(l)
		if ind < minFold || ind == 0 {
			break
		}
		c := l[ind:]
		if strings.HasPrefix(c, "#") {
			break
		}
		if isSeqEntry(c) || findKeyColon(c) >= 0 {
			break
		}
		for ; blanks > 0; blanks-- {
			parts = append(parts, "")
		}
		parts = append(parts, strings.TrimRight(stripComment(c), " \t"))
		pos++
		blanks = 0
	}
	pos -= blanks
	var sb strings.Builder
	for i, s := range parts {
		if i > 0 {
			if s == "" || parts[i-1] == "" {
				sb.WriteByte('\n')
			} else {
				sb.WriteByte(' ')
			}
		}
		sb.WriteString(s)
	}
	val := strings.TrimRight(sb.String(), "\n")
	return &Node{Kind: ScalarNode, Style: Plain, Value: val, Line: pos}, pos, nil
}

func stripComment(s string) string {
	depth := 0
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\'', '"':
			q := s[i]
			i++
			for i < len(s) && s[i] != q {
				if s[i] == '\\' && q == '"' {
					i++
				}
				i++
			}
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case '#':
			if i == 0 || s[i-1] == ' ' || s[i-1] == '\t' {
				return s[:i]
			}
		}
	}
	return s
}

func (p *parser) scalarFromText(text string, line int) (*Node, error) {
	anchor, tag, rest, err := splitProperties(text)
	if err != nil {
		return nil, err
	}
	if rest == "" {
		return &Node{Kind: ScalarNode, Tag: "!!null", Anchor: anchor, Line: line}, nil
	}
	if rest[0] == '\'' || rest[0] == '"' {
		sub := &parser{lines: []string{rest}}
		c := &cursor{p: sub, line: 0, col: 0}
		n, err := sub.readQuoted(c)
		if err != nil {
			return nil, err
		}
		n.Anchor = anchor
		if tag != "" {
			n.Tag = tag
		}
		n.Line = line
		return n, nil
	}
	if rest[0] == '[' || rest[0] == '{' {
		sub := &parser{lines: []string{rest}, anchors: p.anchors}
		c := &cursor{p: sub, line: 0, col: 0}
		n, err := sub.flowNode(c)
		if err != nil {
			return nil, err
		}
		n.Anchor = anchor
		n.Line = line
		return n, nil
	}
	n := &Node{Kind: ScalarNode, Style: Plain, Value: strings.TrimRight(stripComment(rest), " \t"), Anchor: anchor, Tag: tag, Line: line}
	p.register(n)
	return n, nil
}

