func parseYAMLInt(v string) (any, bool) {
	s := strings.ReplaceAll(v, "_", "")
	if s == "" {
		return nil, false
	}
	sign := ""
	body := s
	if body[0] == '-' || body[0] == '+' {
		sign, body = string(body[0]), body[1:]
	}
	if body == "" {
		return nil, false
	}
	base := 0
	switch {
	case strings.HasPrefix(body, "0x") || strings.HasPrefix(body, "0X"):
		base, body = 16, body[2:]
	case strings.HasPrefix(body, "0o") || strings.HasPrefix(body, "0O"):
