		return math.Inf(1), true
	case "-.inf", "-.Inf", "-.INF":
		return math.Inf(-1), true
	case ".nan", ".NaN", ".NAN":
		return math.NaN(), true
	}
	if !floatRe.MatchString(s) {
		return 0, false
	}
	f, err := strconv.ParseFloat(s, 64)
