}

type decoder struct {
	anchors map[string]any
	nodes   map[string]*Node
	depth   int
}

// ToAny converts a node tree into plain Go values.
func (p *parser) toAny(n *Node) (any, error) {
	d := &decoder{nodes: p.anchors, anchors: map[string]any{}}
	return d.node(n)
}

func (d *decoder) node(n *Node) (any, error) {
	if n == nil {
		return nil, nil
	}
	d.depth++
	if d.depth > 10000 {
		return nil, fmt.Errorf("yaml: document contains excessive aliasing")
	}
	defer func() { d.depth-- }()
	switch n.Kind {
	case AliasNode:
		target, ok := d.nodes[n.Value]
		if !ok {
			return nil, fmt.Errorf("yaml: unknown anchor '%s' referenced", n.Value)
		}
		return d.node(target)
	case ScalarNode:
		return resolveScalar(n), nil
	case SequenceNode:
		out := make([]any, 0, len(n.Children))
		for _, c := range n.Children {
			v, err := d.node(c)
			if err != nil {
				return nil, err
			}
			out = append(out, v)
		}
		return out, nil
	case MappingNode:
		out := map[string]any{}
		lines := map[string]int{}
		var errs []string
		for i := 0; i+1 < len(n.Children); i += 2 {
			kn, vn := n.Children[i], n.Children[i+1]
			if kn.Kind == ScalarNode && kn.Value == "<<" && kn.Style == Plain {
				merged, err := d.node(vn)
				if err != nil {
					return nil, err
				}
				mergeInto(out, merged)
				continue
			}
			kv, err := d.node(kn)
			if err != nil {
				return nil, err
			}
			key := keyString(kv)
			if prev, dup := lines[key]; dup {
				errs = append(errs, fmt.Sprintf("line %d: mapping key %q already defined at line %d", kn.Line, key, prev))
				continue
			}
			lines[key] = kn.Line
			v, err := d.node(vn)
			if err != nil {
				return nil, err
			}
			out[key] = v
		}
		if len(errs) > 0 {
			return nil, &TypeError{Errors: errs}
		}
		return out, nil
	}
	return nil, nil
}

func mergeInto(dst map[string]any, src any) {
	switch s := src.(type) {
	case map[string]any:
		for k, v := range s {
			if _, ok := dst[k]; !ok {
				dst[k] = v
			}
		}
	case []any:
		for _, item := range s {
			mergeInto(dst, item)
		}
	}
}

func keyString(v any) string {
	switch k := v.(type) {
	case string:
		return k
	case nil:
		return "null"
	case bool:
		return strconv.FormatBool(k)
	case int:
		return strconv.Itoa(k)
	case int64:
		return strconv.FormatInt(k, 10)
	case uint64:
		return strconv.FormatUint(k, 10)
	case float64:
		return formatFloat(k)
	case time.Time:
		return k.Format(time.RFC3339Nano)
	}
	return fmt.Sprint(v)
}

// Unmarshal decodes the first document into a generic Go value.
func Unmarshal(data []byte) (any, error) {
	p := &parser{}
	docs, err := parseWith(p, data)
	if err != nil {
		return nil, err
	}
	if len(docs) == 0 {
		return nil, nil
	}
	return p.toAny(docs[0])
}

// UnmarshalAll decodes every document in the stream.
func UnmarshalAll(data []byte) ([]any, error) {
	p := &parser{}
	docs, err := parseWith(p, data)
	if err != nil {
		return nil, err
	}
	out := make([]any, 0, len(docs))
	for _, d := range docs {
		v, err := p.toAny(d)
		if err != nil {
			return nil, err
		}
		out = append(out, v)
	}
	return out, nil
}

func parseWith(p *parser, data []byte) ([]*Node, error) {
	text := string(data)
	text = strings.ReplaceAll(text, "\r\n", "\n")
	text = strings.ReplaceAll(text, "\r", "\n")
	text = strings.TrimSuffix(text, "\n")
	if len(data) > 0 {
		p.lines = strings.Split(text, "\n")
	}
	pos := 0
	var docs []*Node
	for {
		n, next, ok, err := p.parseDocument(pos)
		if err != nil {
			return nil, err
		}
		if !ok {
			break
		}
		docs = append(docs, n)
		if next <= pos && next < len(p.lines) {
			next = pos + 1
		}
		pos = next
		if pos >= len(p.lines) {
			break
		}
	}
	return docs, nil
}

// UnmarshalMap decodes the first document, requiring a mapping at the root.
func UnmarshalMap(data []byte) (map[string]any, error) {
	v, err := Unmarshal(data)
	if err != nil {
		return nil, err
	}
	switch t := v.(type) {
	case nil:
		return map[string]any{}, nil
	case map[string]any:
		return t, nil
	}
	return nil, typeErrorf("line 1: cannot unmarshal %s into map[string]interface {}", shortTag(v))
}

// UnmarshalSlice decodes the first document, requiring a sequence at the root.
func UnmarshalSlice(data []byte) ([]any, error) {
	v, err := Unmarshal(data)
	if err != nil {
		return nil, err
	}
	switch t := v.(type) {
	case nil:
		return []any{}, nil
	case []any:
		return t, nil
	}
	return nil, typeErrorf("line 1: cannot unmarshal %s into []interface {}", shortTag(v))
}

func shortTag(v any) string {
	switch v.(type) {
	case nil:
		return "!!null"
	case bool:
		return "!!bool"
	case int, int64, uint64:
		return "!!int"
	case float64:
		return "!!float"
	case string:
		return "!!str"
	case []any:
		return "!!seq"
	case map[string]any:
		return "!!map"
	case time.Time:
		return "!!timestamp"
	}
	return "!!str"
}

